async function search(p){p=p||{};var q=pmText(p.keyword),page=Number(p.page==null?1:p.page);if(!q)return [];if(q.length>60||!Number.isSafeInteger(page)||page<1||page>2000)throw new Error('关键词或页码无效');var encoded=encodeURIComponent(q),html=await zmGet('/vodsearch/'+encoded+'-------------.html');if(page>1){var $=await Widget.html.load(html),max=1;$('#page a').each(function(i,e){var path=$(e).attr('href')||'',m=path.match(/^\/vodsearch\/([A-Za-z\d%_-]+?)----------(\d+)---\.html$/);if(m&&m[1]===encoded)max=Math.max(max,Number(m[2]));});if(page>max)return [];html=await zmGet('/vodsearch/'+encoded+'----------'+page+'---.html');var next=await Widget.html.load(html);if(Number(pmText(next('#page .page-current').text()))!==page)throw new Error('追影猫搜索分页不匹配');}return zmCards(html);}
async function zmSubject(id){return pmOnce('zm.subject.'+id,async function(){var $=await Widget.html.load(await zmGet('/voddetail/'+id+'.html')),title=pmText($('.module-info-heading h1').first().text()),cover=pmCover(ZM_SITE,$('.module-info-poster img').first().attr('data-original')),sources=[],seen=Object.create(null);if(!title)throw new Error('追影猫详情结构已变化');$('#playsx .search-result-list > a').each(function(i,e){var a=$(e),u=a.attr('href'),name=pmText(a.text()).replace(/推荐$/,'');try{pmUrl(u);}catch(e){return;}if(seen[u])return;seen[u]=true;var m=u.match(/^https:\/\/www\.jpyy2\.com\/detail\/(\d{1,10})$/),mt=u.match(/^https:\/\/www\.mtyy7\.com\/voddetail\/(\d{1,10})\.html$/);sources.push({name:name,url:u,kind:m?'gp':mt?'mt':null,id:m?m[1]:mt?mt[1]:null});});if(!sources.length)throw new Error('追影猫没有返回来源');var link=ZM_SITE+'/voddetail/'+id+'.html',item={id:link,type:'url',link:link,title:title,coverUrl:cover,posterPath:cover,description:pmText($('.module-info-introduction-content').first().text())};return {item:item,sources:sources};});}
function zmTitle(s){return pmText(s).replace(/[\s·:：]/g,'');}
async function zmMtDetail(source,title){var url=ZM_MT+'/voddetail/'+source.id+'.html',$=await Widget.html.load(await pmHtml(url,pmHeaders(ZM_MT))),actual=pmText($('.slide-info-title, .vod-detail h1').first().text());if(!actual){var m=($('title').text()||'').match(/^(.+?)(?:电视剧|电影|动漫|综艺|免费高清)/);actual=m?pmText(m[1]):'';}if(zmTitle(actual)!==zmTitle(title))throw new Error('麦田来源影片名称不匹配');var tabs=$('.anthology-tab a'),groups=$('.anthology-list-play'),lines=[],seen=Object.create(null);groups.each(function(i,e){var list=[],sid=null;$(e).find('a[href^="/vodplay/"]').each(function(j,e){var a=$(e),m=(a.attr('href')||'').match(/^\/vodplay\/(\d+)-(\d+)-(\d+)\.html$/);if(!m||m[1]!==source.id||Number(m[3])<1||sid!==null&&sid!==m[2])throw new Error('麦田分集不匹配');sid=m[2];if(seen[a.attr('href')])throw new Error('麦田分集重复');seen[a.attr('href')]=true;list.push({path:a.attr('href'),index:Number(m[3]),title:pmText(a.text())});});if(!list.length)return;list.sort(function(a,b){return a.index-b.index;});list.forEach(function(e,i){if(e.index!==i+1||!e.title)throw new Error('麦田分集不完整');});if(list.length>10000)throw new Error('麦田分集数量异常');var name=pmText(tabs.eq(i).text()).replace(/\d+$/,'');lines.push({sid:sid,name:name||'麦田线路 '+sid,episodes:list});});if(!lines.length||lines.length>40)throw new Error('麦田未返回分集');return {kind:'mt',source:source,lines:lines};}
async function zmAdapt(source,title){if(source.kind==='gp'){var d=await gpDetail(source.id);if(zmTitle(d.item.title)!==zmTitle(title))throw new Error('金牌来源影片名称不匹配');return {kind:'gp',source:source,lines:[{sid:'1',name:source.name+'游客',episodes:d.episodes.map(function(e){return {index:e.index,nid:e.nid,title:e.title};})}]};}if(source.kind==='mt')return zmMtDetail(source,title);throw new Error('此来源尚未适配原生播放');}
async function zmResolved(ids){var subject=await zmSubject(ids.id),supported=subject.sources.filter(function(s){return s.kind&&(ids.source?s.kind===ids.source&&s.id===ids.sourceId:true);}).sort(function(a,b){return (a.kind==='gp'?0:1)-(b.kind==='gp'?0:1);}),errors=[];for(var i=0;i<supported.length;i++)try{return {subject:subject,adapted:await zmAdapt(supported[i],subject.item.title)};}catch(e){if(e.code==='RATE_LIMIT'||e.code==='CHALLENGE')throw e;errors.push(supported[i].name+'：'+e.message);}throw new Error('追影猫此影片尚无可用的已适配来源'+(errors.length?'（'+errors.join('；')+'）':''));}
async function loadDetail(link){var ids=zmParse(link),resolved=await zmResolved(ids),a=resolved.adapted,item=Object.assign({},resolved.subject.item),line=ids.source==='mt'?a.lines.find(function(l){return l.sid===ids.nid;}):a.lines.slice().sort(function(x,y){return y.episodes.length-x.episodes.length;})[0];if(!line)throw new Error('追影猫所选线路不存在');item.description+='\n来源：'+resolved.subject.sources.map(function(s){return s.name;}).join('、')+'\n当前分集来源：'+a.source.name+' · 实际 '+line.episodes.length+' 集';item.episodeItems=line.episodes.map(function(ep){var nid=a.kind==='gp'?ep.nid:line.sid,u=zmLink(ids.id,a.kind,a.source.id,nid,ep.index);return {id:u,type:'url',link:u,title:/^\d+$/.test(ep.title)?'第'+Number(ep.title)+'集':ep.title,coverUrl:item.coverUrl,childItems:a.lines.map(function(l){var e=l.episodes.find(function(x){return pmEpisodeKey(x)===pmEpisodeKey(ep);});if(!e)return null;var u=zmLink(ids.id,a.kind,a.source.id,a.kind==='gp'?e.nid:l.sid,e.index);return {id:u,type:'url',link:u,title:l.name+' · '+e.title,coverUrl:item.coverUrl};}).filter(Boolean)};});return item;}
async function zmMtPlayer(html,id,sid,index){var $=await Widget.html.load(html),players=[];$('script:not([src])').each(function(i,e){var s=$(e).html()||'',m=s.match(/\bvar\s+player_[A-Za-z\d_]+\s*=\s*(\{)/);if(m)players.push(pmLiteral(s,m.index+m[0].length-1));});if(players.length!==1)throw new Error('麦田播放参数已变化');var p=players[0];if(String(p.id)!==id||String(p.sid)!==sid||Number(p.nid)!==index)throw new Error('麦田播放参数与所选分集不匹配');if(Number(p.encrypt)!==0)throw new Error('麦田此线路需要专用网页解析，请换线路');var url=pmUrl(p.url);if(!/\.(?:m3u8|mp4)(?:[?#]|$)/i.test(url))throw new Error('麦田此线路暂未提供直连，请换线路');return url;}
async function zmResources(ids,q){if(!ids.source)throw new Error('请先选择追影猫分集');var r=await zmResolved(ids),a=r.adapted;if(a.kind==='gp'){var ep=a.lines[0].episodes.find(function(e){return e.nid===ids.nid&&e.index===ids.index;});if(!ep)throw new Error('金牌来源分集不匹配');return gpResources({id:a.source.id,nid:ep.nid},q);}var selected=a.lines.find(function(l){return l.sid===ids.nid;}),ep=selected&&selected.episodes.find(function(e){return e.index===ids.index;});if(!ep)throw new Error('麦田来源分集不匹配');var candidates=[{line:selected,ep:ep}];a.lines.forEach(function(l){if(l.sid===selected.sid)return;var other=l.episodes.find(function(e){return pmEpisodeKey(e)===pmEpisodeKey(ep);});if(other)candidates.push({line:l,ep:other});});var out=[],errors=[],seen=Object.create(null),budget={reads:0,maxReads:6};for(var i=0;i<Math.min(candidates.length,3);i++){var c=candidates[i];try{var page=await pmHtml(ZM_MT+c.ep.path,pmHeaders(ZM_MT)),url=await zmMtPlayer(page,a.source.id,c.line.sid,c.ep.index),headers=pmHeaders(ZM_MT,c.ep.path);headers.Accept='*/*';if(seen[url])continue;seen[url]=true;var info=/\.m3u8(?:[?#]|$)/i.test(url)?await pmHls(url,headers,q,budget):await pmMp4(url,headers);out.push({name:c.line.name+' · '+ep.title+(info.height?' · 清单 '+info.width+'×'+info.height:''),url:info.url,playerType:'app',customHeaders:headers});}catch(e){if(e.code==='RATE_LIMIT'||e.code==='CHALLENGE')throw e;errors.push(c.line.name+'：'+e.message);}}if(!out.length)throw new Error('麦田线路检查失败：'+errors.join('；'));return out;}
async function loadResource(p){p=typeof p==='string'?{link:p}:p||{};var ids=zmParse(p.link),q=p.qualityPreference||'highest';if(['highest','fixed'].indexOf(q)<0)throw new Error('画质选项无效');return pmOnce('zm.stream.'+p.link+'|'+q,function(){return zmResources(ids,q);});}
